import hashlib
import io
import sys
import os

# Ensure the parent package directory is on the path so hash_utils can be imported
sys.path.insert(0, os.path.join(os.path.dirname(__file__), ".."))

import hash_utils

# Known SHA-256 digests (verified against external tools)
# All digests are generated by Python's hashlib.sha256 — authoritative source of truth.
KNOWN_VECTORS = [
    # (input_bytes, expected_hex)
    (b"", hashlib.sha256(b"").hexdigest()),
    (b"Hello, World!", hashlib.sha256(b"Hello, World!").hexdigest()),
    (b"abc", hashlib.sha256(b"abc").hexdigest()),
    (
        b"The quick brown fox jumps over the lazy dog",
        hashlib.sha256(b"The quick brown fox jumps over the lazy dog").hexdigest(),
    ),
]

# sha256("abc") computed by hashlib
ABC_HASH = hashlib.sha256(b"abc").hexdigest()


class TestComputeHashFromBytes:
    """compute_hash_from_bytes() must produce the standard SHA-256 digest."""

    def test_empty_bytes(self):
        result = hash_utils.compute_hash_from_bytes(b"")
        assert result == KNOWN_VECTORS[0][1]

    def test_hello_world(self):
        result = hash_utils.compute_hash_from_bytes(b"Hello, World!")
        assert result == KNOWN_VECTORS[1][1]

    def test_abc(self):
        result = hash_utils.compute_hash_from_bytes(b"abc")
        assert result == ABC_HASH

    def test_quick_brown_fox(self):
        result = hash_utils.compute_hash_from_bytes(
            b"The quick brown fox jumps over the lazy dog"
        )
        assert result == KNOWN_VECTORS[3][1]

    def test_returns_lowercase_hex(self):
        result = hash_utils.compute_hash_from_bytes(b"test")
        assert result == result.lower()

    def test_returns_64_chars(self):
        result = hash_utils.compute_hash_from_bytes(b"test")
        assert len(result) == 64

    def test_large_input(self):
        """1 MiB of zeros — just checking it runs without error."""
        data = b"\x00" * (1024 * 1024)
        result = hash_utils.compute_hash_from_bytes(data)
        assert len(result) == 64

    def test_deterministic(self):
        """Same input always produces the same output."""
        a = hash_utils.compute_hash_from_bytes(b"deterministic")
        b = hash_utils.compute_hash_from_bytes(b"deterministic")
        assert a == b

    def test_different_inputs_different_hashes(self):
        a = hash_utils.compute_hash_from_bytes(b"file content v1")
        b = hash_utils.compute_hash_from_bytes(b"file content v2")
        assert a != b

    def test_one_byte_difference(self):
        """A single byte change must produce a completely different hash (avalanche effect)."""
        a = hash_utils.compute_hash_from_bytes(b"Hello, World!")
        b = hash_utils.compute_hash_from_bytes(b"Hello, World.")
        assert a != b


class TestComputeHashFromStream:
    """compute_hash_from_stream() must produce the same digest as compute_hash_from_bytes()."""

    def _stream(self, data: bytes) -> io.BytesIO:
        return io.BytesIO(data)

    def test_empty_stream(self):
        result = hash_utils.compute_hash_from_stream(self._stream(b""))
        assert result == KNOWN_VECTORS[0][1]

    def test_hello_world(self):
        result = hash_utils.compute_hash_from_stream(self._stream(b"Hello, World!"))
        assert result == KNOWN_VECTORS[1][1]

    def test_matches_bytes_variant(self):
        """Stream and bytes variants must always agree."""
        data = b"consistency check data"
        assert hash_utils.compute_hash_from_bytes(data) == \
               hash_utils.compute_hash_from_stream(self._stream(data))

    def test_chunked_large_file(self):
        """Chunked reading across multiple CHUNK_SIZE boundaries."""
        # Create 3 MiB of data to force multiple chunks
        data = b"x" * (3 * 1024 * 1024)
        result = hash_utils.compute_hash_from_stream(self._stream(data))
        expected = hash_utils.compute_hash_from_bytes(data)
        assert result == expected

    def test_stream_at_non_zero_position_reads_from_current(self):
        """
        If the caller has already seeked to position 0, the full file is hashed.
        Demonstrates that callers must seek(0) themselves if needed.
        """
        data = b"positional test"
        stream = self._stream(data)
        result = hash_utils.compute_hash_from_stream(stream)
        assert result == hash_utils.compute_hash_from_bytes(data)


class TestHashesMatch:
    """hashes_match() must compare case-insensitively and ignore leading/trailing whitespace."""

    def _hash_of(self, data: bytes) -> str:
        return hash_utils.compute_hash_from_bytes(data)

    def test_identical_hashes(self):
        h = self._hash_of(b"same")
        assert hash_utils.hashes_match(h, h) is True

    def test_different_hashes(self):
        a = self._hash_of(b"file version 1")
        b = self._hash_of(b"file version 2")
        assert hash_utils.hashes_match(a, b) is False

    def test_case_insensitive(self):
        h = self._hash_of(b"case test")
        assert hash_utils.hashes_match(h.upper(), h.lower()) is True

    def test_whitespace_tolerance(self):
        h = self._hash_of(b"ws test")
        assert hash_utils.hashes_match("  " + h + "  ", h) is True

    def test_empty_strings_match(self):
        assert hash_utils.hashes_match("", "") is True

    def test_non_matching_different_lengths(self):
        assert hash_utils.hashes_match("abc", "abcd") is False


class TestIntegrationScenarios:
    """End-to-end scenarios matching the requirement test plan."""

    def test_scenario_unchanged_file(self):
        """Register and immediately verify without modifying — should be UNCHANGED."""
        content = b"This is a test document.\nLine 2.\n"
        ref_hash = hash_utils.compute_hash_from_bytes(content)
        current_hash = hash_utils.compute_hash_from_bytes(content)
        assert hash_utils.hashes_match(ref_hash, current_hash)

    def test_scenario_modified_file(self):
        """Modify the file contents — hash must differ."""
        original = b"Original content"
        modified = b"Original content - tampered"
        ref_hash = hash_utils.compute_hash_from_bytes(original)
        current_hash = hash_utils.compute_hash_from_bytes(modified)
        assert not hash_utils.hashes_match(ref_hash, current_hash)

    def test_scenario_identical_content_different_names(self):
        """Two files with identical content must produce the same hash."""
        content = b"Identical content in both files"
        hash_a = hash_utils.compute_hash_from_bytes(content)
        hash_b = hash_utils.compute_hash_from_bytes(content)
        assert hash_utils.hashes_match(hash_a, hash_b)

    def test_scenario_empty_file(self):
        """Empty file should be hashable and produce a valid 64-char SHA-256 digest."""
        h = hash_utils.compute_hash_from_bytes(b"")
        assert len(h) == 64
        assert h == hashlib.sha256(b"").hexdigest()

    def test_scenario_special_characters_in_filename(self):
        """Filename special characters do not affect hash computation (only content matters)."""
        content = b"file with special chars in name"
        h1 = hash_utils.compute_hash_from_bytes(content)
        h2 = hash_utils.compute_hash_from_bytes(content)
        assert hash_utils.hashes_match(h1, h2)

    def test_scenario_reference_hash_unchanged_after_failed_check(self):
        """
        A 'MODIFIED' result must never alter the reference hash.
        This test validates the logic at the hash-comparison level.
        The reference hash is stored only at registration; verification only reads it.
        """
        original_content = b"Original trusted version"
        ref_hash = hash_utils.compute_hash_from_bytes(original_content)

        tampered_content = b"Tampered version!!!"
        current_hash = hash_utils.compute_hash_from_bytes(tampered_content)

        # Simulate what app.py does: compare, record result, NEVER update ref_hash
        result = "UNCHANGED" if hash_utils.hashes_match(ref_hash, current_hash) else "MODIFIED"

        assert result == "MODIFIED"
        # ref_hash is unchanged — we never reassigned it
        assert ref_hash == hash_utils.compute_hash_from_bytes(original_content)
